// Package db is asparges' persistence layer: one SQLite file holding events,
// photos, their crops and the gallery order. The schema is applied through
// squibble from the embedded schema.sql; every query is generated by sqlc
// into db/dbsqlc. Domain rules live in site/, which is the intended caller.
package db

import (
	"context"
	"database/sql"
	_ "embed"
	"errors"
	"fmt"

	"github.com/juanfont/headscale/hscontrol/db/sqliteconfig"
	"github.com/tailscale/squibble"
	"modernc.org/sqlite"
	sqlite3 "modernc.org/sqlite/lib"

	"github.com/kradalby/asparges/db/dbsqlc"
)

//go:embed schema.sql
var dbSchema string

// schema is the squibble migration target. Schema changes append
// {Source, Target, Apply} rules whose digests chain to the hash of schema.sql.
// Squibble's digest sees columns only: a rule must also make every changed
// CHECK, key and index, or production silently keeps the old ones. Each
// change keeps the schema it replaces as testdata/schema-<digest>.sql, and
// TestMigratedEqualsFresh fails until a database made from every one of them
// migrates to exactly what a fresh one holds.
//
// IgnoreTables keeps litestream's bookkeeping tables out of the digest:
// litestream replicates this database and creates them at runtime, and
// squibble would otherwise refuse to open a database with unexpected tables.
var schema = &squibble.Schema{
	Current:      dbSchema,
	IgnoreTables: []string{"_litestream_seq", "_litestream_lock"},
	Updates: []squibble.UpdateRule{
		{
			Source: "db50b8097147ab6b24a06f3c5535ef7e4351cf2324754ef6469294668d924a61",
			Target: "7a8d1b74975279810b002c7c1a615cbe118ecfecc88f90ae57ac7662c373661f",
			Apply: squibble.Exec(`CREATE TABLE settings (
    name  TEXT PRIMARY KEY,
    value TEXT NOT NULL
) WITHOUT ROWID;`),
		},
		{
			Source: "7a8d1b74975279810b002c7c1a615cbe118ecfecc88f90ae57ac7662c373661f",
			Target: "e1cd24d3375aad77a05d966425975e8cd3133740471d1b86e0563b8eba44afa6",
			// Existing events keep the slug they have: nobody can tell now
			// whether it was typed.
			Apply: squibble.Exec(`ALTER TABLE events ADD COLUMN slug_from_title INTEGER NOT NULL DEFAULT 0 CHECK (slug_from_title IN (0, 1));`),
		},
	},
}

// DB is the asparges store.
type DB struct {
	sql *sql.DB
	q   *dbsqlc.Queries
}

// Open opens (creating if needed) the SQLite database at path and migrates it
// to the embedded schema.
func Open(ctx context.Context, path string) (*DB, error) {
	cfg := sqliteconfig.Default(path)
	// Set on each new connection, auto_vacuum takes the write lock, so a
	// read that needed a connection waited for any write under way, up to
	// the busy timeout and past its own context. It is kept in the file, so
	// setAutoVacuum sets it once instead.
	cfg.AutoVacuum = ""

	uri, err := cfg.ToURL()
	if err != nil {
		return nil, fmt.Errorf("building sqlite uri: %w", err)
	}

	sqlDB, err := sql.Open("sqlite", uri)
	if err != nil {
		return nil, fmt.Errorf("opening sqlite: %w", err)
	}

	if err := setAutoVacuum(ctx, sqlDB); err != nil {
		_ = sqlDB.Close()
		return nil, err
	}

	if err := schema.Apply(ctx, sqlDB); err != nil {
		_ = sqlDB.Close()
		return nil, fmt.Errorf("applying schema: %w", err)
	}

	return &DB{sql: sqlDB, q: dbsqlc.New(sqlDB)}, nil
}

// setAutoVacuum makes the file give back the space of deleted rows
// (incremental auto_vacuum). An existing file takes the mode only through
// VACUUM, which is run once, when the mode is not set yet.
func setAutoVacuum(ctx context.Context, sqlDB *sql.DB) error {
	// One connection: the mode set on it is what its VACUUM writes.
	conn, err := sqlDB.Conn(ctx)
	if err != nil {
		return fmt.Errorf("connecting: %w", err)
	}
	defer conn.Close()

	// Pragmas are outside sqlc; these maintenance statements are the
	// exception.
	var mode int
	if err := conn.QueryRowContext(ctx, "PRAGMA auto_vacuum").Scan(&mode); err != nil {
		return fmt.Errorf("reading auto_vacuum: %w", err)
	}

	const incremental = 2
	if mode == incremental {
		return nil
	}

	for _, stmt := range []string{"PRAGMA auto_vacuum = INCREMENTAL", "VACUUM"} {
		if _, err := conn.ExecContext(ctx, stmt); err != nil {
			return fmt.Errorf("%s: %w", stmt, err)
		}
	}

	return nil
}

// Close closes the database.
func (d *DB) Close() error { return d.sql.Close() }

// Queries returns the generated queries, bound to the database itself.
func (d *DB) Queries() *dbsqlc.Queries { return d.q }

// InTx runs fn in one transaction, committed when fn returns nil.
func (d *DB) InTx(ctx context.Context, fn func(*dbsqlc.Queries) error) error {
	tx, err := d.sql.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("beginning transaction: %w", err)
	}
	// A no-op after commit; on the error paths the error that matters is fn's.
	defer func() { _ = tx.Rollback() }()

	if err := fn(d.q.WithTx(tx)); err != nil {
		return err
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("committing: %w", err)
	}

	return nil
}

// ReadTx runs fn in one read transaction: every query in it sees the same
// committed state, whatever commits meanwhile. It takes no write lock, so it
// never waits for a writer, nor a writer for it.
func (d *DB) ReadTx(ctx context.Context, fn func(*dbsqlc.Queries) error) error {
	tx, err := d.sql.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return fmt.Errorf("beginning read transaction: %w", err)
	}
	// Nothing to commit: a read ends by letting go of its snapshot.
	defer func() { _ = tx.Rollback() }()

	return fn(d.q.WithTx(tx))
}

// IsUniqueViolation reports whether err is a UNIQUE or PRIMARY KEY conflict.
func IsUniqueViolation(err error) bool {
	return hasCode(err, sqlite3.SQLITE_CONSTRAINT_UNIQUE, sqlite3.SQLITE_CONSTRAINT_PRIMARYKEY)
}

// IsForeignKeyViolation reports whether err is a FOREIGN KEY failure: a row
// that points at a missing one, or a delete of a row still pointed at.
func IsForeignKeyViolation(err error) bool {
	return hasCode(err, sqlite3.SQLITE_CONSTRAINT_FOREIGNKEY)
}

func hasCode(err error, codes ...int) bool {
	var serr *sqlite.Error
	if !errors.As(err, &serr) {
		return false
	}

	for _, c := range codes {
		if serr.Code() == c {
			return true
		}
	}

	return false
}
